/* Liens du menu principal */
.footer-nav-link {
    position: relative;
    display: inline-block;
    padding-bottom: 2px;
    transition: color 0.3s ease;
}
.footer-nav-link::after {
    content: '';
    position: absolute;
    width: 0;
    height: 1px;
    bottom: 0;
    left: 50%;
    background-color: #9d623d;
    transition: all 0.3s ease;
    transform: translateX(-50%);
}
.footer-nav-link:hover {
    color: #9d623d;
}
.footer-nav-link:hover::after {
    width: 100%;
}

/* Liens d'action (Réservations) */
.footer-action-link {
    display: inline-block;
    border-bottom: 1px solid rgba(113, 53, 6, 0.3);
    padding-bottom: 4px;
    transition: all 0.3s ease;
}
.footer-action-link:hover {
    color: #9d623d;
    border-color: #9d623d;
    transform: translateY(-2px);
}

@media (prefers-reduced-motion: reduce) {
    .footer-nav-link,
    .footer-nav-link::after,
    .footer-action-link,
    .tripadvisor-badge img {
        transition: none !important;
    }
}

lv-452a4a4cd6fa:
body { margin: 0; padding: 0; background-color: #fcf9f3; }

/* --- CADRE VIDÉO FENÊTRE EN ARCHE ÉPURÉE --- */
.arched-video-frame {
    position: relative;
    background: #ffffff;
    padding: 10px;
    border-radius: 140px 140px 0 0;
    border: 1px solid #713506;
    box-shadow: 0 25px 50px -12px rgba(113, 53, 6, 0.15);
    overflow: hidden;
    transition: transform 0.5s ease, box-shadow 0.5s ease;
    margin: 3rem auto;
    max-width: 380px;
    opacity: 0;
    transform: translateY(40px);
}
.arched-video-frame.is-visible {
    opacity: 1;
    transform: translateY(0);
}
.arched-video-frame:hover {
    transform: translateY(-8px);
    box-shadow: 0 30px 60px -15px rgba(113, 53, 6, 0.25);
}
.arched-video-frame::before {
    content: '';
    position: absolute;
    top: 8px; bottom: 8px; left: 8px; right: 8px;
    border: 1px solid rgba(157, 98, 61, 0.6);
    border-radius: 132px 132px 0 0;
    pointer-events: none;
    z-index: 30;
}
.video-mask {
    position: relative;
    width: 100%;
    aspect-ratio: 9/16;
    border-radius: 130px 130px 0 0;
    overflow: hidden;
    background-color: #000;
}
.video-mask video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    z-index: 10;
    position: relative;
}

/* --- BOUTONS PREMIUM (GLASSMORPHISM) --- */
.glass-btn {
    background: rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.4);
    color: #ffffff;
    transition: all 0.3s ease;
}
.glass-btn:hover {
    background: rgba(255, 255, 255, 0.9);
    color: #713506;
    transform: scale(1.1);
}
.video-controls {
    opacity: 0;
    transition: opacity 0.4s ease;
}
.arched-video-frame:hover .video-controls {
    opacity: 1;
}

/* --- LETTRINE (Drop Cap) --- */
.drop-cap::first-letter {
    font-family: 'Great Vibes', cursive;
    font-size: 5.5rem;
    float: left;
    line-height: 0.85;
    margin-right: 0.5rem;
    color: #9d623d;
}

/* Style éditorial pour l'encart d'information */
.info-card {
    background-image: repeating-linear-gradient(0deg, transparent, transparent 39px, rgba(157, 98, 61, 0.1) 39px, rgba(157, 98, 61, 0.1) 40px);
    background-color: #ffffff;
    border: 1px solid rgba(113, 53, 6, 0.2);
}

@media (prefers-reduced-motion: reduce) {
    .arched-video-frame,
    .glass-btn,
    .video-controls,
    .hover\:scale-105 {
        transition: none !important;
    }
}

