.lv-menu-summary::-webkit-details-marker {
  display: none;
}

.lv-menu-panel {
  display: none;
  position: absolute;
  top: calc(100% + 14px);
  left: 0;
  width: min(360px, calc(100vw - 32px));
  background: #fcf9f3;
  border: 1px solid rgba(157, 98, 61, 0.18);
