  height: 100%;
}

.lv-hero-bg img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.lv-hero-img-desktop {
  display: block;
  object-position: center 34%;
}

.lv-hero-img-mobile {
  display: none;
  object-position: center 20%;
}

.lv-hero-overlay {
