/* --- FILTRE ÉLÉGANT SANS BUG DE COULEUR (PALACE STYLE) --- */
.village-img-wrapper {
    position: relative;
    overflow: hidden;
}

/* Calque de fusion cuivré signature (Archive) */
.village-img-wrapper::after {
    content: '';
    position: absolute;
    inset: 0;
    background-color: #9d623d; /* Cuivré */
    mix-blend-mode: color;
    opacity: 0.85;
    transition: opacity 0.8s ease;
    pointer-events: none;
    z-index: 10;
}

/* Voile de texture ancienne */
.village-img-wrapper::before {
    content: '';
    position: absolute;
    inset: 0;
    background-color: rgba(113, 53, 6, 0.15); 
    transition: opacity 0.8s ease;
    pointer-events: none;
    z-index: 11;
}

/* Déclenchement au SURVOL de la souris OU au SCROLL (.is-visible) */
.group:hover .village-img-wrapper::after,
.group:hover .village-img-wrapper::before,
.group.is-visible .village-img-wrapper::after,
.group.is-visible .village-img-wrapper::before {
    opacity: 0;
}

/* Mouvement de l'image doux et luxueux */
.village-img {
    transition: transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
    will-change: transform;
}

/* Zoom au SURVOL ou au SCROLL */
.group:hover .village-img,
.group.is-visible .village-img {
    transform: scale(1.05);
}

