/* --- DESIGN ARCHE SOBRE ET ÉLÉGANT --- */
.mini-arched-video {
    position: relative;
    background: #ffffff; /* Passe-partout blanc pur et sobre */
    padding: 8px; /* Finesse du cadre */
    border-radius: 120px 120px 0 0;
    border: 1px solid #713506; /* Ligne marron signature */
    box-shadow: 0 15px 30px -10px rgba(113, 53, 6, 0.10); /* Ombre très douce */
    overflow: hidden;
    transition: transform 0.5s ease, box-shadow 0.5s ease;
    margin: 10px auto 0;
    max-width: 220px; 
    opacity: 0;
    transform: translateY(20px);
}

.mini-arched-video.is-visible {
    opacity: 1;
    transform: translateY(0);
}

.mini-arched-video:hover {
    transform: translateY(-6px);
    box-shadow: 0 20px 40px -12px rgba(113, 53, 6, 0.18);
}

/* Liseré cuivré intérieur très discret */
.mini-arched-video::before {
    content: '';
    position: absolute;
    top: 6px; bottom: 6px; left: 6px; right: 6px;
    border: 1px solid rgba(157, 98, 61, 0.4);
    border-radius: 114px 114px 0 0;
    pointer-events: none;
    z-index: 30;
}

/* Masque de la vidéo */
.mini-video-mask {
    position: relative;
    width: 100%;
    aspect-ratio: 9/16;
    border-radius: 112px 112px 0 0;
    overflow: hidden;
    background-color: #000;
}

.mini-video-mask video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    z-index: 10;
    position: relative;
}

/* Voile sombre subtil en bas pour faire ressortir les boutons en verre au survol */
.mini-video-mask::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 35%;
    background: linear-gradient(to top, rgba(0,0,0,0.6) 0%, transparent 100%);
    pointer-events: none;
    z-index: 20;
    opacity: 0;
