lv-0a59827b680e:
body { margin: 0; padding: 0; }

/* --- BOUTONS LUXE (Lignes fines et animations douces) --- */
.btn-luxury {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 16px 42px;
    border: 1px solid rgba(113, 53, 6, 0.15); /* Bordure très fine et discrète */
    color: #713506;
    font-family: 'Poppins', sans-serif;
    font-size: 12px; /* Plus petit pour l'élégance */
    font-weight: 400;
    text-transform: uppercase;
    letter-spacing: 0.15em; /* Très espacé */
    text-decoration: none;
    background-color: transparent;
    overflow: hidden;
    transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
}

/* Le fond qui monte subtilement au survol */
.btn-luxury::before {
    content: '';
    position: absolute;
    inset: 0;
    background-color: rgba(113, 53, 6, 0.03); /* Voile à peine perceptible */
    transform: scaleY(0);
    transform-origin: bottom;
    transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    z-index: 0;
}

.btn-luxury:hover {
    border-color: rgba(113, 53, 6, 0.6); /* La bordure s'affirme */
}

.btn-luxury:hover::before {
    transform: scaleY(1);
}

/* Conteneur du texte pour rester au-dessus du fond animé */
.btn-luxury-text {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
}

/* L'icône flèche qui se décale */
.btn-luxury-arrow {
    margin-left: 12px;
    transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.btn-luxury:hover .btn-luxury-arrow {
    transform: translateX(6px);
}

