    .nav-links-village .village-link:hover::after {
        width: 100% !important;
    }

    /* --- CADRE VIDÉO FENÊTRE EN ARCHE ÉPURÉE --- */
    .arched-video-frame {
        position: relative;
        background: #ffffff;
        padding: 10px;
        border-radius: 140px 140px 0 0;
        border: 1px solid rgba(113, 53, 6, 0.2);
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
        overflow: hidden;
        transition: transform 0.5s ease, box-shadow 0.5s ease;
        margin: 0 auto;
    }
    .arched-video-frame:hover {
        transform: translateY(-8px);
        box-shadow: 0 30px 60px -15px rgba(0, 0, 0, 0.4);
    }
    .arched-video-frame::before {
        content: '';
        position: absolute;
        top: 8px; bottom: 8px; left: 8px; right: 8px;
        border: 1px solid rgba(157, 98, 61, 0.6);
        border-radius: 132px 132px 0 0;
        pointer-events: none;
        z-index: 30;
    }
    .video-mask {
        position: relative;
        width: 100%;
        aspect-ratio: 9/16;
        border-radius: 130px 130px 0 0;
        overflow: hidden;
        background-color: #000000;
        display: flex;
        justify-content: center;
        align-items: center;
    }
    .video-mask video {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        z-index: 10;
        position: relative;
    }

    /* --- BOUTONS PREMIUM (GLASSMORPHISM) --- */
    .glass-btn {
        background: rgba(255, 255, 255, 0.25);
        backdrop-filter: blur(8px);
        -webkit-backdrop-filter: blur(8px);
        border: 1px solid rgba(255, 255, 255, 0.4);
        color: #ffffff;
        transition: all 0.3s ease;
    }
    .glass-btn:hover {
        background: #ffffff;
        color: #713506;
        transform: scale(1.1);
    }
    .video-controls {
        opacity: 0;
        transition: opacity 0.4s ease;
    }
    .arched-video-frame:hover .video-controls {
        opacity: 1;
    }

    /* Style encart info */
    .info-card {
        background-image: repeating-linear-gradient(0deg, transparent, transparent 39px, rgba(157, 98, 61, 0.1) 39px, rgba(157, 98, 61, 0.1) 40px);
        background-color: #ffffff;
        border: 1px solid rgba(113, 53, 6, 0.2);
    }

    /* --- ENCADRÉ MAILLAGE INTERNE : PROGRAMME JAZZ AU CHÂTEAU --- */
    .jazz-program-card {
        position: relative;
        overflow: hidden;
        background: linear-gradient(135deg, rgba(113, 53, 6, 0.98), rgba(157, 98, 61, 0.92));
        border: 1px solid rgba(245, 240, 234, 0.35);
        box-shadow: 0 22px 44px -18px rgba(64, 28, 4, 0.5);
    }
    .jazz-program-card::before,
    .jazz-program-card::after {
        content: '';
        position: absolute;
        border: 1px solid rgba(245, 240, 234, 0.28);
        border-radius: 999px;
        pointer-events: none;
    }
    .jazz-program-card::before {
        width: 280px;
        height: 280px;
        top: -155px;
        right: -80px;
    }
    .jazz-program-card::after {
        width: 180px;
        height: 180px;
        bottom: -120px;
        left: -60px;
    }
