        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        background: #ffffff;
        color: #713506;
        text-decoration: none;
        font-family: 'Lato', sans-serif;
        font-size: 13px;
        font-weight: 600;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        padding: 15px 22px;
        transition: transform .28s ease, background-color .28s ease, color .28s ease;
    }
    .program-link-btn:hover {
        transform: translateY(-3px);
        background: #f5f0ea;
        color: #713506;
    }

    /* --- VIDÉO YOUTUBE INTÉGRÉE AU DESIGN ÉDITORIAL --- */
