/* --- BANDEAU DE NAVIGATION (Sur une seule ligne avec scroll horizontal) --- */
.carte-nav-wrapper {
    position: sticky;
    top: 0;
    z-index: 50;
    background-color: rgba(252, 249, 243, 0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(113, 53, 6, 0.15);
    margin-bottom: 40px;
}

.carte-nav {
    max-width: 1200px;
    margin: 0 auto;
    padding: 16px 20px;
    display: flex;
    justify-content: flex-start; /* Alignement à gauche pour le scroll mobile */
    gap: 24px;
    flex-wrap: nowrap; /* Empêche le passage à la ligne */
    overflow-x: auto; /* Active le défilement horizontal */
    -webkit-overflow-scrolling: touch; /* Défilement fluide sur iOS */
    scrollbar-width: none; /* Cache la barre de scroll Firefox */
}

/* Centrer sur les grands écrans si l'espace le permet */
@media (min-width: 1200px) {
    .carte-nav { justify-content: center; }
}

/* Cache la barre de scroll Chrome/Safari */
.carte-nav::-webkit-scrollbar { 
    display: none; 
}

.carte-nav-link {
    font-family: 'Poppins', sans-serif;
    font-size: 13px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    text-decoration: none;
    color: #713506;
    position: relative;
    padding-bottom: 6px;
    font-weight: 500;
    white-space: nowrap; /* Obligatoire pour garder le texte sur une ligne */
    transition: opacity 0.25s ease;
}

.carte-nav-link:hover {
    opacity: 0.7;
}

.carte-nav-link::after {
    content: "";
    position: absolute;
    left: 50%;
    bottom: 0;
    width: 0%;
    height: 1px;
    background-color: #9d623d;
    transition: width 0.3s ease;
    transform: translateX(-50%);
}

.carte-nav-link:hover::after {
    width: 100%;
}

/* Ornement décoratif pour le titre Midi */
.section-ornament {
    width: 40px;
    height: 1px;
    background-color: #9d623d;
    margin: 0 auto 2.5rem auto;
    opacity: 0.5;
}

