/* --- FILTRE ÉLÉGANT SANS BUG DE COULEUR (PALACE STYLE) --- */
.village-img-wrapper {
    position: relative;
    overflow: hidden;
    background-color: #713506; 
}

/* Calque de fusion cuivré signature (Archive) */
.village-img-wrapper::after {
    content: '';
    position: absolute;
    inset: 0;
    background-color: #9d623d; 
    mix-blend-mode: color;
    opacity: 0.85;
    transition: opacity 1.8s cubic-bezier(0.25, 1, 0.5, 1); /* Transition lente et luxueuse */
    pointer-events: none;
    z-index: 10;
}

/* Voile de profondeur */
.village-img-wrapper::before {
    content: '';
    position: absolute;
    inset: 0;
    background-color: rgba(113, 53, 6, 0.15); 
    transition: opacity 1.8s cubic-bezier(0.25, 1, 0.5, 1);
    pointer-events: none;
    z-index: 11;
}

/* Transition d'apparition progressive au scroll (Staggering) */
.scroll-anim-trigger.is-visible:nth-child(1) .village-img-wrapper::after,
.scroll-anim-trigger.is-visible:nth-child(1) .village-img-wrapper::before {
    opacity: 0;
    transition-delay: 0.3s; /* La première commence après 300ms */
}

.scroll-anim-trigger.is-visible:nth-child(2) .village-img-wrapper::after,
.scroll-anim-trigger.is-visible:nth-child(2) .village-img-wrapper::before {
    opacity: 0;
    transition-delay: 0.8s; /* La deuxième commence après 800ms */
}

.scroll-anim-trigger.is-visible:nth-child(3) .village-img-wrapper::after,
.scroll-anim-trigger.is-visible:nth-child(3) .village-img-wrapper::before {
    opacity: 0;
    transition-delay: 1.3s; /* La troisième commence après 1.3s */
