    transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
    box-shadow: 0 10px 20px -5px rgba(113, 53, 6, 0.08);
}
.btn-luxury::before {
    content: '';
    position: absolute;
    inset: 0;
    background-color: rgba(113, 53, 6, 0.04);
    transform: scaleY(0);
    transform-origin: bottom;
    transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    z-index: 0;
}
.btn-luxury:hover {
    border-color: rgba(113, 53, 6, 0.6);
    box-shadow: 0 15px 30px -5px rgba(113, 53, 6, 0.15);
    transform: translateY(-2px);
}
.btn-luxury:hover::before { transform: scaleY(1); }
.btn-luxury-text { position: relative; z-index: 1; display: flex; align-items: center; }
.btn-luxury-arrow { margin-left: 12px; transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1); }
.btn-luxury:hover .btn-luxury-arrow { transform: translateX(6px); }

/* --- FILTRE CUIVRÉ SIGNATURE --- */
.village-img-wrapper {
    position: relative;
    overflow: hidden;
    background-color: #713506;
}
/* Calque Cuivré */
.village-img-wrapper::after {
    content: ''; position: absolute; inset: 0;
    background-color: #9d623d; mix-blend-mode: color; opacity: 0.85; 
    transition: opacity 0.6s ease; pointer-events: none; z-index: 10;
}
/* Calque Profondeur */
.village-img-wrapper::before {
    content: ''; position: absolute; inset: 0;
    background-color: rgba(113, 53, 6, 0.15); 
    transition: opacity 0.6s ease; pointer-events: none; z-index: 11;
}
/* Estompage du filtre uniquement au Survol */
.group:hover .village-img-wrapper::after, 
.group:hover .village-img-wrapper::before { 
    opacity: 0; 
}

/* Mouvement lent luxueux */
.village-img { 
    transition: transform 0.8s cubic-bezier(0.4, 0, 0.2, 1); 
    will-change: transform; 
}
.group:hover .village-img { 
    transform: scale(1.05); 
}

