body { margin: 0; padding: 0; background-color: #fcf9f3; }

/* --- LETTRINE (Drop Cap) --- */
.drop-cap::first-letter {
    font-family: 'Great Vibes', cursive;
    font-size: 5.5rem;
    float: left;
    line-height: 0.85;
    margin-right: 0.5rem;
    color: #9d623d;
}

/* --- IMAGE ENCADRÉE TYPE MENU (Cliquable) --- */
.menu-presentation-frame {
    background: #ffffff;
    padding: 12px;
    border: 1px solid rgba(113, 53, 6, 0.15);
    box-shadow: 0 25px 50px -12px rgba(113, 53, 6, 0.12);
    transition: transform 0.4s ease, box-shadow 0.4s ease;
    border-radius: 2px;
    width: 100%;
    position: relative;
    display: block;
    text-decoration: none;
}
.menu-presentation-frame:hover {
    transform: translateY(-5px);
    box-shadow: 0 30px 60px -15px rgba(113, 53, 6, 0.20);
}
.menu-image-inner {
    position: relative;
    width: 100%;
    overflow: hidden;
    border: 1px solid rgba(157, 98, 61, 0.3);
}
.menu-image-inner img {
    width: 100%;
    display: block;
    transition: transform 0.8s ease;
}
.menu-presentation-frame:hover .menu-image-inner img {
    transform: scale(1.03);
}

